"""The tallybook HTTP JSON API, built on ``http.server``.

``serve(db_path, host, port, today)`` runs it; ``make_server`` builds the server without running it
(used by ``serve`` and by tests).  Every request opens the book for itself and closes it again.
"""

import datetime
import json
import re
import signal
import socket
import sys
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qsl, unquote

from tallybook import __version__
from tallybook.budgets import Budget, budget_status
from tallybook.dates import Period, format_date, parse_date
from tallybook.errors import NotFoundError, ParseError, TallybookError, ValidationError
from tallybook.export import (money_to_dict, transaction_to_dict, transactions_to_csv,
                              transactions_to_json)
from tallybook.journal import format_journal
from tallybook.model import Posting, Transaction
from tallybook.money import Money
from tallybook.recurring import Recurring
from tallybook.reports import (balance_sheet, cashflow, income_statement, register, render_text,
                               trial_balance)
from tallybook.storage import Store

MAX_BODY = 1048576
MAX_DRAIN = 64 * 1024 * 1024
MAX_INT = 9223372036854775807
_DIGITS = re.compile(r"[0-9]+\Z")
_REASONS = {200: "OK", 201: "Created", 400: "Bad Request", 404: "Not Found", 405: "Method Not Allowed",
            409: "Conflict", 413: "Payload Too Large", 415: "Unsupported Media Type",
            500: "Internal Server Error"}
_STATUS_OF_CODE = {"parse": 400, "validation": 400, "not_found": 404, "conflict": 409}
_JSON_TYPES = ("application/json",)
_IMPORT_TYPES = ("application/json", "text/csv", "text/plain")
_REPORT_NAMES = ("trial-balance", "balance-sheet", "income-statement", "cashflow", "register")


class Text(object):
    """A non-JSON answer body."""

    def __init__(self, text, content_type="text/plain; charset=utf-8"):
        self.text = text
        self.content_type = content_type


def dump_json(value):
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


# --------------------------------------------------------------------------- request helpers

class Request(object):
    """What a handler gets: decoded path pieces, query, body, and the server's settings."""

    def __init__(self, method, pieces, query, body, content_type, db_path, today):
        self.method = method
        self.content_type = content_type
        self.pieces = pieces
        self.query = query
        self.body = body
        self.db_path = db_path
        self._today = today
        self._json = None

    @property
    def today(self):
        return self._today or datetime.date.today()

    def store(self):
        return Store.open(self.db_path)

    # query parameters
    def q_text(self, name, required=False):
        if name in self.query:
            return self.query[name]
        if required:
            raise ValidationError("missing parameter: %s" % name)
        return None

    def q_bool(self, name, default):
        value = self.query.get(name)
        if value is None:
            return default
        return _to_bool(value, "parameter '%s'" % name)

    def q_int(self, name):
        value = self.query.get(name)
        if value is None:
            return None
        if not _DIGITS.match(value) or int(value) > MAX_INT:
            raise ValidationError("parameter '%s' must be a whole number from 0 to %d" % (name, MAX_INT))
        return int(value)

    def q_date(self, name, required=False):
        value = self.q_text(name, required)
        return None if value is None else parse_date(value)

    def q_period(self, name, required=False):
        value = self.q_text(name, required)
        return None if value is None else Period.parse(value)

    # JSON body
    def json_body(self):
        if self._json is None:
            self._json = _parse_json_object(self.body)
        return self._json


def _to_bool(value, what):
    low = value.lower()
    if low in ("true", "yes", "1"):
        return True
    if low in ("false", "no", "0"):
        return False
    raise ValidationError("%s must be true, false, yes, no, 1 or 0, not %r" % (what, value))


def _decode_utf8(data):
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise ParseError("body is not valid UTF-8")


def _reject_constant(name):
    raise ValueError("invalid JSON constant %s" % name)


def _parse_json_object(data):
    if not data:
        return {}
    text = _decode_utf8(data)
    try:
        value = json.loads(text, parse_constant=_reject_constant)
    except (ValueError, RecursionError) as exc:
        raise ParseError("body is not valid JSON: %s" % exc)
    if not isinstance(value, dict):
        raise ValidationError("body must be a JSON object")
    return value


def _check_fields(obj, allowed, required=()):
    for name in sorted(obj):
        if name not in allowed:
            raise ValidationError("unknown field: %s" % name)
    for name in required:
        if obj.get(name) is None:
            raise ValidationError("missing field: %s" % name)


def _text(obj, name, default=None):
    value = obj.get(name)
    if value is None:
        return default
    if not isinstance(value, str):
        raise ValidationError("field '%s' must be text" % name)
    return value


def _date(obj, name, default=None):
    value = _text(obj, name)
    return default if value is None else parse_date(value)


def _money(value, name):
    if isinstance(value, str):
        return Money.parse(value)
    if isinstance(value, dict):
        if (set(value) != {"amount", "currency"}
                or not isinstance(value["amount"], str) or not isinstance(value["currency"], str)):
            raise ValidationError("field '%s' must be an object with the text fields amount and currency"
                                  % name)
        return Money.of(value["amount"], value["currency"])
    raise ValidationError("field '%s' must be an amount: text such as \"12.50 USD\" or an object" % name)


def _postings(obj):
    value = obj.get("postings")
    if not isinstance(value, list):
        raise ValidationError("field 'postings' must be a list")
    result = []
    for item in value:
        if not isinstance(item, dict):
            raise ValidationError("each posting must be an object")
        _check_fields(item, ("account", "amount", "note"), ("account",))
        account = _text(item, "account")
        amount = item.get("amount")
        result.append(Posting(account, None if amount is None else _money(amount, "amount"),
                              _text(item, "note", "")))
    return result


def _tags(obj):
    value = obj.get("tags")
    if value is None:
        return ()
    if not isinstance(value, list) or not all(isinstance(t, str) for t in value):
        raise ValidationError("field 'tags' must be a list of text")
    return tuple(value)


def _template(obj, start):
    if not isinstance(obj, dict):
        raise ValidationError("field 'template' must be an object")
    _check_fields(obj, ("payee", "narration", "flag", "tags", "postings"), ("payee", "postings"))
    return Transaction(start, _text(obj, "payee"), _text(obj, "narration", ""), _postings(obj),
                       _tags(obj), _text(obj, "flag", "*"))


# --------------------------------------------------------------------------- JSON shapes

def account_dict(account):
    return {"path": account.path, "type": account.type, "currency": account.currency,
            "opened": None if account.opened is None else format_date(account.opened),
            "closed": None if account.closed is None else format_date(account.closed),
            "note": account.note}


def rate_dict(row):
    src, dst, on, rate_text = row
    return {"src": src, "dst": dst, "date": format_date(on), "rate": rate_text}


def budget_dict(budget):
    return {"pattern": budget.pattern, "period_kind": budget.period_kind,
            "amount": money_to_dict(budget.amount), "start": format_date(budget.start)}


def recurring_dict(rec):
    template = rec.template
    return {"name": rec.name, "schedule": str(rec.schedule), "start": format_date(rec.start),
            "end": None if rec.end is None else format_date(rec.end), "count": rec.count,
            "template": {"payee": template.payee, "narration": template.narration, "flag": template.flag,
                         "tags": sorted(set(template.tags)),
                         "postings": [{"account": p.account, "amount": money_to_dict(p.amount),
                                       "note": p.note} for p in template.postings]}}


# --------------------------------------------------------------------------- endpoints

def h_health(req):
    with req.store() as store:
        return 200, {"status": "ok", "version": __version__, "schema_version": store.version}


def h_accounts_list(req):
    kind = req.q_text("type")
    under = req.q_text("under")
    currency = req.q_text("currency")
    include_closed = req.q_bool("include_closed", True)
    with req.store() as store:
        accounts = store.accounts(type=kind, under=under, currency=currency, include_closed=include_closed)
        return 200, [account_dict(a) for a in accounts]


def h_accounts_add(req):
    body = req.json_body()
    _check_fields(body, ("path", "type", "currency", "opened", "note"), ("path",))
    path = _text(body, "path")
    kind = _text(body, "type")
    currency = _text(body, "currency")
    opened = _date(body, "opened")
    note = _text(body, "note", "")
    with req.store() as store:
        return 201, account_dict(store.add_account(path, type=kind, currency=currency, opened=opened,
                                                   note=note))


def h_account_get(req):
    with req.store() as store:
        return 200, account_dict(store.get_account(req.pieces[1]))


def h_account_close(req):
    body = req.json_body()
    _check_fields(body, ("on",))
    on = _date(body, "on", None) or req.today
    with req.store() as store:
        return 200, account_dict(store.close_account(req.pieces[1], on))


def h_transactions_list(req):
    query = req.q_text("q")
    limit = req.q_int("limit")
    offset = req.q_int("offset")
    with req.store() as store:
        total = store.count_transactions(query)
        items = store.transactions(query, limit, 0 if offset is None else offset)
        return 200, {"items": [transaction_to_dict(t) for t in items], "total": total, "limit": limit,
                     "offset": 0 if offset is None else offset}


def h_transactions_add(req):
    body = req.json_body()
    _check_fields(body, ("date", "payee", "narration", "flag", "tags", "postings"),
                  ("date", "payee", "postings"))
    tx = Transaction(_date(body, "date"), _text(body, "payee"), _text(body, "narration", ""),
                     _postings(body), _tags(body), _text(body, "flag", "*"))
    with req.store() as store:
        return 201, transaction_to_dict(store.add_transaction(tx))


def _tx_id(req):
    value = int(req.pieces[1])
    if value > MAX_INT:
        raise NotFoundError("no transaction %s" % req.pieces[1].lstrip("0"))
    return value


def h_transaction_get(req):
    tx_id = _tx_id(req)
    with req.store() as store:
        return 200, transaction_to_dict(store.get_transaction(tx_id))


def h_transaction_delete(req):
    tx_id = _tx_id(req)
    with req.store() as store:
        return 200, transaction_to_dict(store.delete_transaction(tx_id))


def h_rates_list(req):
    with req.store() as store:
        return 200, [rate_dict(r) for r in store.rate_rows()]


def h_rates_put(req):
    body = req.json_body()
    _check_fields(body, ("src", "dst", "date", "rate"), ("src", "dst", "date", "rate"))
    src, dst, rate = _text(body, "src"), _text(body, "dst"), body["rate"]
    if not isinstance(rate, str):
        raise ValidationError("field 'rate' must be text")
    on = _date(body, "date")
    with req.store() as store:
        store.set_rate(src, dst, rate, on)
        return 200, {"src": src, "dst": dst, "date": format_date(on), "rate": rate}


def h_rates_delete(req):
    src = req.q_text("src", True)
    dst = req.q_text("dst", True)
    on = req.q_date("date", True)
    with req.store() as store:
        found = [r for r in store.rate_rows() if r[0] == src and r[1] == dst and r[2] == on]
        store.remove_rate(src, dst, on)
        if not found:
            raise NotFoundError("no rate %s -> %s set on %s" % (src, dst, format_date(on)))
        return 200, rate_dict(found[0])


def h_budgets_list(req):
    with req.store() as store:
        return 200, [budget_dict(b) for b in store.budgets()]


def h_budgets_add(req):
    body = req.json_body()
    fields = ("pattern", "period_kind", "amount", "start")
    _check_fields(body, fields, fields)
    pattern, kind = body["pattern"], body["period_kind"]
    for name, value in (("pattern", pattern), ("period_kind", kind)):
        if not isinstance(value, str):
            raise ValidationError("field '%s' must be text" % name)
    budget = Budget(pattern, kind, _money(body["amount"], "amount"), _date(body, "start"))
    with req.store() as store:
        store.add_budget(budget)
        return 201, budget_dict(budget)


def h_budgets_delete(req):
    pattern = req.q_text("pattern", True)
    kind = req.q_text("period_kind", True)
    with req.store() as store:
        found = [b for b in store.budgets() if b.pattern == pattern and b.period_kind == kind]
        store.remove_budget(pattern, kind)
        return 200, budget_dict(found[0])


def h_budgets_status(req):
    period = req.q_period("period", True)
    with req.store() as store:
        lines = budget_status(store.budgets(), store.ledger(), period)
        return 200, [line.to_dict() for line in lines]


def h_recurring_list(req):
    with req.store() as store:
        return 200, [recurring_dict(r) for r in store.recurring()]


def h_recurring_add(req):
    body = req.json_body()
    _check_fields(body, ("name", "schedule", "start", "template", "end", "count"),
                  ("name", "schedule", "start", "template"))
    start = _date(body, "start")
    rec = Recurring(body["name"], body["schedule"], _template(body["template"], start), start,
                    _date(body, "end"), body.get("count"))
    with req.store() as store:
        store.add_recurring(rec)
        return 201, recurring_dict(rec)


def h_recurring_delete(req):
    name = req.q_text("name", True)
    with req.store() as store:
        found = [r for r in store.recurring() if r.name == name]
        store.remove_recurring(name)
        return 200, recurring_dict(found[0])


def h_recurring_materialize(req):
    body = req.json_body()
    _check_fields(body, ("upto",))
    upto = _date(body, "upto")
    with req.store() as store:
        made = store.materialize(upto=upto, today=req.today)
        return 200, {"added": [transaction_to_dict(t) for t in made]}


def h_report(req):
    name = req.pieces[1]
    fmt = req.q_text("format")
    if fmt is not None and fmt not in ("json", "text"):
        raise ValidationError("unknown format %r: use json or text" % fmt)
    if name == "trial-balance":
        as_of = req.q_date("as_of")
    elif name == "balance-sheet":
        as_of = req.q_date("as_of")
        convert = req.q_text("convert_to")
    elif name == "income-statement":
        period = req.q_period("period", True)
        convert = req.q_text("convert_to")
    elif name == "cashflow":
        period = req.q_period("period", True)
    else:
        account = req.q_text("account", True)
        period = req.q_period("period")
        rollup = req.q_bool("rollup", False)
    with req.store() as store:
        ledger = store.ledger()
        if name == "trial-balance":
            report = trial_balance(ledger, as_of)
        elif name == "balance-sheet":
            report = balance_sheet(ledger, as_of, convert, today=req.today)
        elif name == "income-statement":
            report = income_statement(ledger, period, convert)
        elif name == "cashflow":
            report = cashflow(ledger, period)
        else:
            report = register(ledger, account, period, rollup)
    if fmt == "text":
        return 200, Text(render_text(report))
    return 200, report


def h_import(req):
    if req.body and req.content_type == "application/json":
        body = req.json_body()
        _check_fields(body, ("csv", "profile", "apply_rules"), ("csv", "profile"))
        text, profile = _text(body, "csv"), _text(body, "profile")
        rules = body.get("apply_rules")
        if rules is not None and not isinstance(rules, bool):
            raise ValidationError("field 'apply_rules' must be true or false")
        apply_rules = True if rules is None else rules
    else:
        profile = req.q_text("profile", True)
        apply_rules = req.q_bool("apply_rules", True)
        text = _decode_utf8(req.body)
    with req.store() as store:
        outcome = store.import_csv(text, profile, apply_rules=apply_rules)
        if outcome.errors:
            raise ValidationError("import failed: " + "; ".join("row %s: %s" % (n, m)
                                                                for n, m in outcome.errors))
        return 200, {"added": [transaction_to_dict(t) for t in outcome.added],
                     "duplicates": [transaction_to_dict(t) for t in outcome.duplicates]}


def h_rules_get(req):
    with req.store() as store:
        return 200, {"rules": store.rules_text()}


def h_rules_put(req):
    body = req.json_body()
    _check_fields(body, ("rules",), ("rules",))
    text = _text(body, "rules")
    with req.store() as store:
        store.set_rules(text)
        return 200, {"rules": store.rules_text()}


def h_export(req):
    fmt = req.q_text("format")
    if fmt is None:
        fmt = "json"
    if fmt not in ("json", "csv", "journal"):
        raise ValidationError("unknown format %r: use json, csv or journal" % fmt)
    with req.store() as store:
        if fmt == "journal":
            return 200, Text(format_journal(store.journal()))
        txs = store.transactions()
    if fmt == "csv":
        return 200, Text(transactions_to_csv(txs), "text/csv; charset=utf-8")
    return 200, Text(transactions_to_json(txs), "application/json; charset=utf-8")


# --------------------------------------------------------------------------- routing

_SIMPLE = {
    "health": {"GET": h_health},
    "accounts": {"GET": h_accounts_list, "POST": h_accounts_add},
    "transactions": {"GET": h_transactions_list, "POST": h_transactions_add},
    "rates": {"DELETE": h_rates_delete, "GET": h_rates_list, "PUT": h_rates_put},
    "budgets": {"DELETE": h_budgets_delete, "GET": h_budgets_list, "POST": h_budgets_add},
    "recurring": {"DELETE": h_recurring_delete, "GET": h_recurring_list, "POST": h_recurring_add},
    "rules": {"GET": h_rules_get, "PUT": h_rules_put},
    "export": {"GET": h_export},
    "import": {"POST": h_import},
}
_PAIRS = {
    ("accounts", None): {"GET": h_account_get},
    ("transactions", None): {"DELETE": h_transaction_delete, "GET": h_transaction_get},
    ("budgets", "status"): {"GET": h_budgets_status},
    ("recurring", "materialize"): {"POST": h_recurring_materialize},
}


def route(pieces):
    """Return the ``{verb: handler}`` table of the path, or None for an unknown path."""
    if not pieces or any(p == "" for p in pieces):
        return None
    if len(pieces) == 1:
        return _SIMPLE.get(pieces[0])
    if len(pieces) == 2:
        first, second = pieces
        if first == "reports":
            return {"GET": h_report} if second in _REPORT_NAMES else None
        if first == "accounts":
            return _PAIRS[("accounts", None)]
        if first == "transactions":
            return _PAIRS[("transactions", None)] if _DIGITS.match(second) else None
        return _PAIRS.get((first, second))
    if len(pieces) == 3 and pieces[0] == "accounts" and pieces[2] == "close":
        return {"POST": h_account_close}
    return None


def split_target(target):
    """Split a request target into decoded path pieces and the query dict (last value wins)."""
    target = target.split("#", 1)[0]
    path, _, query = target.partition("?")
    if not path.startswith("/"):
        return None, {}
    pieces = [unquote(p) for p in path[1:].split("/")]
    params = {}
    for name, value in parse_qsl(query, keep_blank_values=True):
        params[name] = value
    return pieces, params


# --------------------------------------------------------------------------- the server

class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    timeout = 60

    def log_message(self, *args):
        pass

    def log_request(self, *args):
        pass

    def log_error(self, *args):
        pass

    def send_error(self, code, message=None, explain=None):
        self.close_connection = True
        self._reply(400, dump_json({"error": message or "bad request"}), "application/json; charset=utf-8")

    def handle_one_request(self):
        try:
            self.raw_requestline = self.rfile.readline(65537)
            if len(self.raw_requestline) > 65536:
                self.requestline = ""
                self.request_version = ""
                self.command = ""
                self.send_error(400, "request line too long")
                return
            if not self.raw_requestline:
                self.close_connection = True
                return
            if not self.parse_request():
                return
            self.close_connection = True
            self._dispatch()
        except (OSError, ValueError):
            self.close_connection = True

    def handle_expect_100(self):
        return True

    # -- plumbing
    def _reply(self, status, body, content_type, extra=()):
        data = body.encode("utf-8")
        head = ["HTTP/1.1 %d %s" % (status, _REASONS.get(status, "Error")),
                "Content-Type: %s" % content_type, "Content-Length: %d" % len(data), "Connection: close"]
        head.extend("%s: %s" % item for item in extra)
        raw = ("\r\n".join(head) + "\r\n\r\n").encode("latin-1")
        if getattr(self, "command", "") != "HEAD":
            raw += data
        try:
            self.wfile.write(raw)
            self.wfile.flush()
        except OSError:
            pass
        self.close_connection = True

    def _error(self, status, message, extra=()):
        self._reply(status, dump_json({"error": message or "error"}), "application/json; charset=utf-8", extra)

    def _drain(self, count):
        remaining = min(count, MAX_DRAIN)
        while remaining > 0:
            chunk = self.rfile.read(min(65536, remaining))
            if not chunk:
                break
            remaining -= len(chunk)

    def _drain_declared(self):
        text = (self.headers.get("Content-Length") or "").strip()
        if _DIGITS.match(text):
            self._drain(int(text))

    def _dispatch(self):
        words = self.requestline.split()
        pieces, query = split_target(words[1] if len(words) > 1 else self.path)
        verbs = route(pieces) if pieces is not None else None
        if verbs is None:
            self._drain_declared()
            self._error(404, "no such path")
            return
        method = self.command
        if method not in verbs:
            self._drain_declared()
            self._error(405, "method %s not allowed here" % method, [("Allow", ", ".join(sorted(verbs)))])
            return
        length_text = self.headers.get("Content-Length")
        length = 0
        if length_text is not None:
            if not _DIGITS.match(length_text.strip()):
                self._error(400, "invalid Content-Length")
                return
            length = int(length_text.strip())
        has_body = method in ("POST", "PUT")
        if not has_body:
            self._drain(length)
            body = b""
        elif length > MAX_BODY:
            self._drain(length)
            self._error(413, "body too large: at most %d bytes" % MAX_BODY)
            return
        else:
            body = self._read_exact(length)
            if body is None:
                self._error(400, "incomplete body")
                return
        ctype = (self.headers.get("Content-Type") or "").split(";", 1)[0].strip().lower()
        if has_body and body:
            allowed = _IMPORT_TYPES if pieces == ["import"] else _JSON_TYPES
            if ctype not in allowed:
                self._error(415, "unsupported content type; use %s" % " or ".join(allowed))
                return
        req = Request(method, pieces, query, body, ctype, self.server.db_path, self.server.today)
        try:
            status, payload = verbs[method](req)
        except TallybookError as exc:
            self._error(_STATUS_OF_CODE.get(exc.code, 400), exc.message)
            return
        except Exception:
            self._error(500, "internal error")
            return
        if isinstance(payload, Text):
            self._reply(status, payload.text, payload.content_type)
        else:
            self._reply(status, dump_json(payload), "application/json; charset=utf-8")

    def _read_exact(self, length):
        chunks = []
        remaining = length
        while remaining > 0:
            chunk = self.rfile.read(min(65536, remaining))
            if not chunk:
                return None
            chunks.append(chunk)
            remaining -= len(chunk)
        return b"".join(chunks)


class ApiServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def handle_error(self, request, client_address):
        pass


class ApiServer6(ApiServer):
    address_family = socket.AF_INET6


def make_server(db_path, host="127.0.0.1", port=0, today=None):
    """Check the book, then bind a server (not yet serving). ``.server_port`` is the real port."""
    with Store.open(db_path) as store:
        store.info()
    cls = ApiServer6 if ":" in host else ApiServer
    server = cls((host, port), Handler)
    server.db_path = db_path
    server.today = today
    return server


def serve(db_path, host="127.0.0.1", port=0, today=None):
    """Serve the book until SIGINT or SIGTERM; returns 0."""
    server = make_server(db_path, host, port, today)
    shown = "[%s]" % host if ":" in host else host
    sys.stdout.write("tallybook listening on http://%s:%d\n" % (shown, server.server_port))
    sys.stdout.flush()
    previous = {}

    def stop(signum, frame):
        threading.Thread(target=server.shutdown, daemon=True).start()

    if threading.current_thread() is threading.main_thread():
        for sig in (signal.SIGINT, signal.SIGTERM):
            previous[sig] = signal.signal(sig, stop)
    try:
        server.serve_forever(poll_interval=0.1)
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
        for sig, old in previous.items():
            signal.signal(sig, old)
    return 0
"""Error hierarchy shared by every tallybook module."""


class TallybookError(Exception):
    """Base of every error caused by what the user asked for.

    ``message`` is the human text, ``code`` a short stable word. ``detail`` is an optional
    dict with extra facts (for example ``{"index": 3}``).
    """

    code = "error"

    def __init__(self, message, code=None, detail=None):
        message = str(message)
        super().__init__(message)
        self.message = message
        if code is not None:
            self.code = code
        self.detail = detail

    def __str__(self):
        return self.message


class ParseError(TallybookError):
    code = "parse"


class ValidationError(TallybookError):
    code = "validation"


class NotFoundError(TallybookError):
    code = "not_found"


class ConflictError(TallybookError):
    code = "conflict"


class LockedPeriodError(ConflictError):
    """The operation touches a date on or before the book's lock date."""

    code = "locked"
