def h_rates_put(req):
    body = req.json_body()
    _check_fields(body, ("src", "dst", "date", "rate"), ("src", "dst", "date", "rate"))
    src, dst, rate = _text(body, "src"), _text(body, "dst"), body["rate"]
    if not isinstance(rate, str):
        raise ValidationError("field 'rate' must be text")
    on = _date(body, "date")
    with req.store() as store:
        store.set_rate(src, dst, rate, on)
        return 200, {"src": src, "dst": dst, "date": format_date(on), "rate": rate}


def h_rates_delete(req):
    src = req.q_text("src", True)
    dst = req.q_text("dst", True)
    on = req.q_date("date", True)
    with req.store() as store:
        found = [r for r in store.rate_rows() if r[0] == src and r[1] == dst and r[2] == on]
        store.remove_rate(src, dst, on)
        if not found:
            raise NotFoundError("no rate %s -> %s set on %s" % (src, dst, format_date(on)))
        return 200, rate_dict(found[0])


