def h_budgets_add(req):
    body = req.json_body()
    fields = ("pattern", "period_kind", "amount", "start")
    _check_fields(body, fields, fields)
    pattern, kind = body["pattern"], body["period_kind"]
    for name, value in (("pattern", pattern), ("period_kind", kind)):
        if not isinstance(value, str):
            raise ValidationError("field '%s' must be text" % name)
    budget = Budget(pattern, kind, _money(body["amount"], "amount"), _date(body, "start"))
    with req.store() as store:
        store.add_budget(budget)
        return 201, budget_dict(budget)


def h_budgets_delete(req):
    pattern = req.q_text("pattern", True)
    kind = req.q_text("period_kind", True)
    with req.store() as store:
        found = [b for b in store.budgets() if b.pattern == pattern and b.period_kind == kind]
        store.remove_budget(pattern, kind)
        return 200, budget_dict(found[0])


